  "<span>First assign a Design Field to at least one object in the design (right panel), then AI will fill them.</span></div></div>": "<span>Zuerst ein Designfeld mindestens einem Objekt im Design zuweisen (rechtes Feld), dann füllt die KI es aus.</span></div></div>",
  "This request comes from the Bulk Builder (PLAN pass). Read the instruction and the design fields, then LIST the outputs you will produce, LABELS ONLY (no field content). Return ONLY a raw JSON object: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. When translate is true the labels are the LANGUAGE NAMES (written in the same language the user used). Otherwise the labels are a distinct short topic/seed per output. Honor any quantity named in the instruction; otherwise a sensible set (about 6 to 12). Hard cap 500.\n": "Diese Anfrage kommt vom Bulk Builder (PLAN-Pass). Lesen Sie die Anweisungen und die Designfelder und listen Sie dann die Ausgaben auf, die Sie erzeugen werden, NUR ETIKETTEN (kein Feldinhalt). Geben Sie NUR ein rohes JSON-Objekt zurück: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. Wenn „Übersetzen“ wahr ist, handelt es sich bei den Beschriftungen um die SPRACHENNAMEN (in derselben Sprache geschrieben, die der Benutzer verwendet hat). Ansonsten handelt es sich bei den Beschriftungen um ein eindeutiges kurzes Thema/Seed pro Ausgabe. Beachten Sie alle in der Anleitung genannten Mengen; ansonsten ein sinnvolles Set (ca. 6 bis 12). Harte Kappe 500.\n",
