  "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">Auto-save times from this browser. The latest state is stored under <span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span>; rolling snapshots use <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">Auto-save times from this browser. The latest state is stored under <span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span>; rolling snapshots use <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p>",
  "<p style=\"color:var(--text-dim);font-size:13px;margin:0\">No <code>dika_autosave</code> entry yet.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin:0\">No <code>dika_autosave</code> entry yet.</p>",
