  "That is everything. Your work stays on this machine.": "Das ist alles. Ihre Arbeit bleibt auf dieser Maschine.",
  "You can reopen this from Settings > About.": "Sie können dies über Einstellungen > Info erneut öffnen.",
  "Start using it": "Beginnen Sie mit der Verwendung",
  "Your profile data is used in contact presets and bulk export.": "Ihre Profildaten werden in Kontaktvoreinstellungen und im Massenexport verwendet.",
  "JOB TITLE": "JOBTITEL",
  "ADDRESS": "ADDRESS",
  "Social Media": "Soziale Medien",
  "Save Profile": "Profil speichern",
  "An account unlocks the online template and asset library, and release news. The editor itself works either way, online or offline.": "Ein Konto schaltet die Online-Vorlagen- und Asset-Bibliothek frei und veröffentlicht Neuigkeiten. Der Editor selbst funktioniert sowohl online als auch offline.",
  "Sign in to unlock:": "Zum Entsperren anmelden:",
  "The online template and asset library": "Die Online-Vorlagen- und Asset-Bibliothek",
  "Release news and early access to new features": "Veröffentlichungsnachrichten und früher Zugriff auf neue Funktionen",
  "The editor itself works either way, with or without an account, online or offline.": "Der Editor selbst funktioniert so oder so, mit oder ohne Konto, online oder offline.",
  "Create an account": "Erstellen Sie ein Konto",
  "WHAT THIS APP SENDS": "WAS DIESE APP SENDET",
  "Once a day: an install id, the app version, your platform and language, and your account id once you sign in.": "Einmal täglich: eine Installations-ID, die App-Version, Ihre Plattform und Sprache sowie Ihre Konto-ID, sobald Sie sich angemeldet haben.",
  "Nothing about your designs. No document, no title, no file name, no image.": "Keine Daten zu Ihren Designs: kein Dokument, Titel, Dateiname oder Bild.",
  "WHERE THE SESSION IS KEPT": "WO DIE SITZUNG GEHALTEN WIRD",
  "You are running the browser build, where every local page shares one storage area, so another local file opened in this browser could read this session. It is therefore short-lived (about 24 hours) and can only read the template library. The desktop app keeps its own isolated storage.": "Sie führen den Browser-Build aus, bei dem jede lokale Seite einen Speicherbereich gemeinsam nutzt, sodass eine andere in diesem Browser geöffnete lokale Datei diese Sitzung lesen kann. Es ist daher kurzlebig (ca. 24 Stunden) und kann nur die Vorlagenbibliothek lesen. Die Desktop-App behält ihren eigenen isolierten Speicher.",
  "Your own keys for the stock media providers. They fill the Images and Audio search tabs, and the GIFs and Stickers tabs in Items. Every provider below has a free tier.": "Ihre eigenen Schlüssel für die Stock-Media-Anbieter. Sie füllen die Suchregisterkarten „Bilder“ und „Audio“ sowie die Registerkarten „GIFs“ und „Aufkleber“ in „Elemente“. Jeder der unten aufgeführten Anbieter verfügt über ein kostenloses Kontingent.",
  "These keys are stored in this browser only, and this build never sends them anywhere except to the provider itself. Anyone with access to this computer or its browser profile can read them, so use a restricted key with the lowest quota you need.": "Diese Schlüssel werden nur in diesem Browser gespeichert und dieser Build sendet sie nirgendwo anders als an den Anbieter selbst. Jeder, der Zugriff auf diesen Computer oder sein Browserprofil hat, kann sie lesen. Verwenden Sie daher einen eingeschränkten Schlüssel mit dem niedrigsten Kontingent, das Sie benötigen.",
  "Save keys": "Schlüssel speichern",
  "1. Go to unsplash.com/oauth/applications and create an app": "1. Gehen Sie zu unsplash.com/oauth/applications und erstellen Sie eine App",
  "2. Copy the Access Key, not the Secret Key": "2. Kopieren Sie den Zugriffsschlüssel, nicht den Geheimschlüssel",
  "Header: Authorization: Client-ID YOUR_KEY - 50 req/hr on demo, 5000 req/hr in production": "Header: Autorisierung: Kunden-ID YOUR_KEY – 50 Anforderungen/Std. in der Demo, 5000 Anforderungen/Std. in der Produktion",
  "1. Go to pexels.com/api and request a key": "1. Gehen Sie zu pexels.com/api und fordern Sie einen Schlüssel an",
  "2. It is issued instantly": "2. Es wird sofort ausgestellt",
  "Header: Authorization: YOUR_KEY - 200 req/hr, 20K req/month": "Header: Autorisierung: YOUR_KEY – 200 Anforderungen/Std., 20.000 Anforderungen/Monat",
  "1. Go to pixabay.com/api/docs/ and sign up": "1. Gehen Sie zu pixabay.com/api/docs/ und registrieren Sie sich",
  "2. Copy the key shown on the docs page": "2. Kopieren Sie den auf der Dokumentenseite angezeigten Schlüssel",
  "500K+ CC-licensed sound effects - header: Authorization: Token YOUR_KEY": "Über 500.000 CC-lizenzierte Soundeffekte – Header: Autorisierung: Token YOUR_KEY",
  "1. Go to freesound.org/apiv2/apply and create an API app": "1. Gehen Sie zu freesound.org/apiv2/apply und erstellen Sie eine API-App",
  "2. Copy the API Token": "2. Kopieren Sie das API-Token",
  "1. Go to devportal.jamendo.com and register an app": "1. Gehen Sie zu devportal.jamendo.com und registrieren Sie eine App",
  "2. Copy the Client ID": "2. Kopieren Sie die Kunden-ID",
  "1. Go to developers.giphy.com and create an app": "1. Gehen Sie zu Developers.giphy.com und erstellen Sie eine App",
  "2. Copy the API Key": "2. Kopieren Sie den API-Schlüssel",
