  "Auto-save times from this browser. The latest state is stored under dika_autosave; rolling snapshots use dika_versions.": "Automatisches Speichern von Zeiten in diesem Browser. Der neueste Status wird unter dika_autosave gespeichert; Rolling Snapshots verwenden dika_versions.",
