  "Deletes every project, page, version, uploaded file, font, brand set, saved key, setting and account on this machine, and puts the app back to how it arrived. It cannot be undone.": "Löscht jedes Projekt, jede Seite, jede Version, jede hochgeladene Datei, jede Schriftart, jeden Markensatz, jeden gespeicherten Schlüssel, jede Einstellung und jedes Konto auf diesem Computer und versetzt die App in den ursprünglichen Zustand zurück. Es kann nicht rückgängig gemacht werden.",
  "Export a project file first if you want to keep anything. This does not uninstall the program itself: use Windows Settings for that.": "Exportieren Sie zunächst eine Projektdatei, wenn Sie etwas behalten möchten. Dadurch wird das Programm selbst nicht deinstalliert. Verwenden Sie dazu die Windows-Einstellungen.",
